INSERT INTO `wp_options` VALUES (10127,'_transient_wcpay_welcome_page_incentive','a:3:{s:9:\"incentive\";a:7:{s:2:\"id\";s:32:\"wcpay-promo-2023-action-discount\";s:4:\"type\";s:12:\"welcome_page\";s:9:\"cta_label\";s:28:\"Install WooPayments for free\";s:6:\"tc_url\";s:75:\"https://woocommerce.com/terms-conditions/woopayments-action-promotion-2023/\";s:11:\"description\";s:117:\"<b>Save 10%</b> on payment processing costs in your <b>first three months</b> when you sign up for WooPayments today.\";s:19:\"task_header_content\";s:256:\"Power your payments with a simple, all-in-one option and <b>save 10% on payment processing costs in your first three months</b>. See <a href=\"https://woocommerce.com/terms-conditions/woopayments-action-promotion-2023/\">Terms and Conditions</a> for details.\";s:10:\"task_badge\";s:35:\"Save 10% on payment processing fees\";}s:12:\"context_hash\";s:32:\"6d37bc19d822af681f896b21065134c7\";s:9:\"timestamp\";i:1730312089;}','off');
