INSERT INTO `wp_postmeta` VALUES (536,2,'_elementor_data','[{\"id\":\"2334a46\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true},\"content_width\":\"full\",\"min_height\":{\"unit\":\"vh\",\"size\":60,\"sizes\":[]},\"min_height_tablet\":{\"unit\":\"vh\",\"size\":\"\",\"sizes\":[]},\"min_height_mobile\":{\"unit\":\"vh\",\"size\":\"\",\"sizes\":[]},\"background_background\":\"video\",\"background_video_link\":\"\\/wp-content\\/uploads\\/2024\\/09\\/LAMA_Intro_Bkgnd.mp4\",\"background_play_on_mobile\":\"yes\"},\"elements\":[],\"isInner\":false},{\"id\":\"b76f199\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"60\",\"right\":\"20\",\"bottom\":\"60\",\"left\":\"20\",\"isLinked\":false},\"flex_gap\":{\"column\":\"50\",\"row\":\"30\",\"isLinked\":false,\"unit\":\"px\",\"size\":50},\"flex_align_items\":\"center\"},\"elements\":[{\"id\":\"b97c9a8\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"flex_gap\":{\"column\":\"50\",\"row\":\"50\",\"isLinked\":true,\"unit\":\"px\",\"size\":50}},\"elements\":[{\"id\":\"c392112\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"297d38e\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Welcome to the Latin American Motorcycle Association (L.A.M.A.) \\n\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=3197874\",\"_background_color\":\"globals\\/colors?id=88133c5\",\"_border_color\":\"globals\\/colors?id=4478c39\"},\"align\":\"left\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"30\",\"bottom\":\"15\",\"left\":\"30\",\"isLinked\":false},\"_background_background\":\"classic\",\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"_box_shadow_box_shadow_type\":\"yes\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"6cbf359\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"editor\":\"<p>The Latin American Motorcycle Association (L.A.M.A.) is a Moto-Tourism club with Democratic ideals. It is one of the most active long-distance riding clubs in the world with 240 chapters in 26 countries and 5 continents. There are nearly 100 L.A.M.A. chapters in the United States alone, and the association is still growing.<\\/p>\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=text\",\"text_color\":\"globals\\/colors?id=3197874\"},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"30\",\"bottom\":\"0\",\"left\":\"30\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"0d86703\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"6b9ea4a\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image\":{\"url\":\"http:\\/\\/test.local\\/wp-content\\/uploads\\/2024\\/09\\/Travel_-_Garden_Group.png\",\"id\":187,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true}],\"isInner\":true},{\"id\":\"0197120\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"background_background\":\"classic\",\"padding\":{\"unit\":\"px\",\"top\":\"30\",\"right\":\"80\",\"bottom\":\"30\",\"left\":\"80\",\"isLinked\":false},\"__globals__\":{\"backgrou