border_color\":\"globals\\/colors?id=4478c39\"},\"align\":\"left\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"30\",\"right\":\"30\",\"bottom\":\"29\",\"left\":\"30\",\"isLinked\":false},\"_background_background\":\"classic\",\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"_box_shadow_box_shadow_type\":\"yes\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"e86c0ba\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"editor\":\"<p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">Thank you for visiting the home of the Latin American Motorcycle Association and the International Motorcycle Association. <\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">\\u00a0<\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">Through these pages, you will learn more about being part of the Best Riders Association in the World! <\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">\\u00a0<\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">We welcome working people from all walks of life to explore the world with us while enjoying the motorcycling lifestyle, spreading peace and love and making lifelong friendships.<\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">\\u00a0<\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">Let\\u2019s Ride!<\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">\\u00a0<\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">Best,<\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">Mario Nieves<\\/span><\\/p>\",\"_padding\":{\"unit\":\"px\",\"top\":\"30\",\"right\":\"50\",\"bottom\":\"50\",\"left\":\"50\",\"isLinked\":false},\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=text\",\"text_color\":\"globals\\/colors?id=3197874\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"286b0f1\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"px\",\"size\":300,\"sizes\":[]},\"width_tablet\":{\"unit\":\"px\",\"size\":\"\",\"sizes\":[]},\"width_mobile\":{\"unit\":\"px\",\"size\":\"\",\"sizes\":[]},\"align\":\"center\",\"text\":\"Divider\",\"weight\":{\"unit\":\"px\",\"size\":5,\"sizes\":[]},\"__globals__\":{\"color\":\"globals\\/colors?id=4478c39\"}},\"elements\":[],\"widgetType\":\"divider\"}],\"isInner\":false},{\"id\":\"b113291\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"flex_justify_content\":\"center\",\"flex_align_items\":\"center\",\"padding\":{\"unit\":\"px\",\"top\":\"80\",\"right\":\"20\",\"bottom\":\"80\",\"left\":\"20\",\"isLinked\":false}},\"elements\":[{\"id\":\"9ee2b35\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Get Connected With L.A.M.A. Today\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=3197874\",\"_background_color\":\"globals\\/colors?id=88133c5\",\"_border_color\":\"globals\\/colors?id=4478c3