INSERT INTO `wp_postmeta` VALUES (7354,833,'_elementor_data','[{\"id\":\"7f80c18e\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"aa6fea9\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image_size\":\"full\",\"width\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]},\"height\":{\"unit\":\"px\",\"size\":700,\"sizes\":[]},\"image\":{\"url\":\"http:\\/\\/test.local\\/wp-content\\/uploads\\/2024\\/10\\/LAMA_Group_Ride_Bogota_2023.jpg\",\"id\":461,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":false},{\"id\":\"1e72b446\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"60\",\"right\":\"20\",\"bottom\":\"60\",\"left\":\"20\",\"isLinked\":false},\"flex_align_items\":\"center\"},\"elements\":[{\"id\":\"77db3cda\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"flex_gap\":{\"column\":\"50\",\"row\":\"50\",\"isLinked\":true,\"unit\":\"px\",\"size\":50}},\"elements\":[{\"id\":\"4cc652fa\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width\":{\"unit\":\"%\",\"size\":40,\"sizes\":[]}},\"elements\":[{\"id\":\"67cf256f\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"History of L.A.M.A,\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=3197874\",\"_background_color\":\"globals\\/colors?id=88133c5\",\"_border_color\":\"globals\\/colors?id=4478c39\"},\"align\":\"center\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"30\",\"right\":\"30\",\"bottom\":\"29\",\"left\":\"30\",\"isLinked\":false},\"_background_background\":\"classic\",\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"_box_shadow_box_shadow_type\":\"yes\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"ffa1a06\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"editor\":\"<p>L.A.M.A. was founded by Mario Nieves in June of 1977 in Chicago\\u2019s notorious Humboldt Park neighborhood. Nieves was inspired to create an inclusive group for motorcycle enthusiasts when he noticed the public perception of motorcycle riders was frequently negative, unlike when he was growing up in Puerto Rico and motorcyclists were considered part of the fabric of the community. He attributes the negative perception to the portrayal of bikers in Hollywood movies and set out to change it.<\\/p>\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=text\",\"text_color\":\"globals\\/colors?id=3197874\"},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"30\",\"bottom\":\"0\",\"left\":\"30\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"727fd06c\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width\":{\"unit\":\"%\",\"size\":60,\"sizes\":[]},\"flex_align_items\":\"center\",\"flex_gap\":{\"column\":\"0\",\"row\":\"0\",\"isLinked\":true,\"unit\":\"px\",\"size\":0}},\"elements\":[{\"id\":\"134c1d29\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image\":{\"url\":\"http:\\/\\/test.local\\/wp-content\\/uploads\\/2024\\/10\\/Couple_Riding_with_Puerto_Rican_Flag_-_Edit_out_LAMA_Station-1.jpg\",\"id\":462,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"a0f4190\",\"elType\":\"container\",\"settings\":{\"boxed_width\":{\"unit\":\"%\",\"size\":20,\"sizes\":[]},\"boxed_width_tablet\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"boxed_width_mobile\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"-40\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"content_width\":\"full\",\"width\":{\"unit\":\"px\",\"size\":500,\"sizes\":[]}},\"elements\":[{\"id\":\"633d6d8\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Founded In 1977 In Chicago By Mario Nieves\",\"align\":\"center\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"30\",\"bottom\":\"15\",\"left\":\"30\",\"isLinked\":false},\"__globals__\":{\"title_color\":\"globals\\/colors?id=88133c5\",\"_background_color\":\"globals\\/colors?id=4478c39\",\"_border_color\":\"globals\\/colors?id=4478c39\"},\"_background_background\":\"classic\",\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"_box_shadow_box_shadow_type\":\"yes\",\"header_size\":\"h5\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":true},{\"id\":\"5658d6b\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"custom_css\":\"selector{\\n    background:linear-gradient(to right, var(--e-global-color-cae35c9) 0, var(--e-global-color-cae35c9) 33%,var(--e-global-color-4671584) 33%, var(--e-global-color-4671584) 66%, #fff 66%, #fff 100%);\\n}\",\"width\":{\"unit\":\"px\",\"size\":300,\"sizes\":[]},\"min_height\":{\"unit\":\"px\",\"size\":10,\"sizes\":[]},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[],\"isInner\":true}],\"isInner\":false},{\"id\":\"6313e11\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"60\",\"right\":\"20\",\"bottom\":\"0\",\"left\":\"20\",\"isLinked\":false},\"flex_gap\":{\"column\":\"80\",\"row\":\"80\",\"isLinked\":true,\"unit\":\"px\",\"size\":80},\"flex_align_items\":\"center\"},\"elements\":[{\"id\":\"9b93cfe\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"A Home For Riders From All Walks Of Life Without Discrimination\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=3197874\"},\"align\":\"center\",\"header_size\":\"h3\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"0ee4e12\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"flex_gap\":{\"column\":\"50\",\"row\":\"50\",\"isLinked\":true,\"unit\":\"px\",\"size\":50}},\"elements\":[{\"id\":\"09d295c\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width\":{\"unit\":\"%\",\"size\":55,\"sizes\":[]},\"flex_align_items\":\"center\",\"flex_gap\":{\"column\":\"0\",\"row\":\"0\",\"isLinked\":true,\"unit\":\"px\",\"size\":0}},\"elements\":[{\"id\":\"6e3761f\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image\":{\"url\":\"http:\\/\\/test.local\\/wp-content\\/uploads\\/2024\\/10\\/Travel_-_Garden_Group.png\",\"id\":468,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"57685e6\",\"elType\":\"container\",\"settings\":{\"boxed_width\":{\"unit\":\"%\",\"size\":20,\"sizes\":[]},\"boxed_width_tablet\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"boxed_width_mobile\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"-40\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"content_width\":\"full\",\"width\":{\"unit\":\"px\",\"size\":500,\"sizes\":[]}},\"elements\":[{\"id\":\"819c737\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"In 1996 A Sister Chapter Was Born In Miami, FL\",\"align\":\"center\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"30\",\"bottom\":\"15\",\"left\":\"30\",\"isLinked\":false},\"__globals__\":{\"title_color\":\"globals\\/colors?id=88133c5\",\"_background_color\":\"globals\\/colors?id=4478c39\",\"_border_color\":\"globals\\/colors?id=4478c39\"},\"_background_background\":\"classic\",\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"_box_shadow_box_shadow_type\":\"yes\",\"header_size\":\"h5\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":true}],\"isInner\":true},{\"id\":\"97fe5ff\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width\":{\"unit\":\"%\",\"size\":40,\"sizes\":[]}},\"elements\":[{\"id\":\"9fdebdd\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"editor\":\"<p>Known by its acronym, L.A.M.A. is a club without borders, a \\u201cHumanist Association\\u201d that accepts working people from all walks of life as members without discrimination based on nationality, race, color, religion, social class, gender, age, motorcycle brand, etc.<\\/p><p>\\u00a0<\\/p><p>L.A.M.A. Chicago was the sole chapter for 19 years until, in 1996, its first sister chapter was born in Miami and the group elected a National President. In 2000, L.A.M.A. celebrated the Millenium by going global, creating L.A.M.A. International Motorcycle Association (I.M.A.) with the addition of chapters in Puerto Rico, Mexico and Cuba. <\\/p>\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=text\",\"text_color\":\"globals\\/colors?id=3197874\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":true},{\"id\":\"3abc4cc\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"flex_gap\":{\"column\":\"50\",\"row\":\"50\",\"isLinked\":true,\"unit\":\"px\",\"size\":50}},\"elements\":[{\"id\":\"cc53327\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width\":{\"unit\":\"%\",\"size\":40,\"sizes\":[]}},\"elements\":[{\"id\":\"d704f92\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"editor\":\"<p>L.A.M.A. continued to expand in 2006 when it introduced Moto-Touring. Moto-Touring is an adventure sport that challenges participants to ride extreme distances, logging miles as they go. L.A.M.A. holds Regional, National, Continental, and World Championships for Moto-Touring, giving members the chance to meet L.A.M.A.s in lands near and far.<\\/p>\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=text\",\"text_color\":\"globals\\/colors?id=3197874\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"ad67122\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width\":{\"unit\":\"%\",\"size\":70,\"sizes\":[]},\"flex_align_items\":\"center\",\"flex_gap\":{\"column\":\"0\",\"row\":\"0\",\"isLinked\":true,\"unit\":\"px\",\"size\":0}},\"elements\":[{\"id\":\"86820a9\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image\":{\"url\":\"http:\\/\\/test.local\\/wp-content\\/uploads\\/2024\\/10\\/LAMAs_on_Route_66.jpg\",\"id\":469,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"full\"},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"3815202\",\"elType\":\"container\",\"settings\":{\"boxed_width\":{\"unit\":\"%\",\"size\":20,\"sizes\":[]},\"boxed_width_tablet\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"boxed_width_mobile\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"-40\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"content_width\":\"full\",\"width\":{\"unit\":\"px\",\"size\":500,\"sizes\":[]}},\"elements\":[{\"id\":\"1e743d4\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"In 2006 Moto-Touring Was Introduced To L.A.M.A.\",\"align\":\"center\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"30\",\"bottom\":\"15\",\"left\":\"30\",\"isLinked\":false},\"__globals__\":{\"title_color\":\"globals\\/colors?id=88133c5\",\"_background_color\":\"globals\\/colors?id=4478c39\",\"_border_color\":\"globals\\/colors?id=4478c39\"},\"_background_background\":\"classic\",\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"_box_shadow_box_shadow_type\":\"yes\",\"header_size\":\"h5\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":true},{\"id\":\"8da270b\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"flex_gap\":{\"column\":\"50\",\"row\":\"50\",\"isLinked\":true,\"unit\":\"px\",\"size\":50}},\"elements\":[{\"id\":\"dd50b98\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width\":{\"unit\":\"%\",\"size\":50,\"sizes\":[]},\"flex_align_items\":\"center\",\"flex_gap\":{\"column\":\"0\",\"row\":\"0\",\"isLinked\":true,\"unit\":\"px\",\"size\":0}},\"elements\":[{\"id\":\"dc14589\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image\":{\"url\":\"http:\\/\\/test.local\\/wp-content\\/uploads\\/2024\\/10\\/Damas_de_LAMA-1.jpg\",\"id\":473,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"full\"},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"c848a59\",\"elType\":\"container\",\"settings\":{\"boxed_width\":{\"unit\":\"%\",\"size\":20,\"sizes\":[]},\"boxed_width_tablet\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"boxed_width_mobile\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"-40\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"content_width\":\"full\",\"width\":{\"unit\":\"px\",\"size\":500,\"sizes\":[]}},\"elements\":[{\"id\":\"eea7fff\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Damas de L.A.M.A. (The Ladies of L.A.M.A.)\",\"align\":\"center\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"30\",\"bottom\":\"15\",\"left\":\"30\",\"isLinked\":false},\"__globals__\":{\"title_color\":\"globals\\/colors?id=88133c5\",\"_background_color\":\"globals\\/colors?id=4478c39\",\"_border_color\":\"globals\\/colors?id=4478c39\"},\"_background_background\":\"classic\",\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"_box_shadow_box_shadow_type\":\"yes\",\"header_size\":\"h5\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":true}],\"isInner\":true},{\"id\":\"e433afb\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width\":{\"unit\":\"%\",\"size\":40,\"sizes\":[]}},\"elements\":[{\"id\":\"3f0b289\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"editor\":\"<p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">Finally, Damas de L.A.M.A. (the ladies of L.A.M.A.) is an important part of the Latin American Motorcycle Association. Their motto: \\u201cWe Ride Our Own\\u201d. Most motorcyclists find traveling extreme distances to be difficult but L.A.M.A. men and women perform these rides often, and they would have it no other way!<\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">\\u00a0<\\/span><\\/p><p class=\\\"paragraph\\\" style=\\\"margin: 0in; vertical-align: baseline;\\\"><span style=\\\"font-family: \'Aptos\',sans-serif;\\\">L.A.M.A.\\/I.M.A. abide by statutes and regulations, and value clear association guidelines internationally. <\\/span><\\/p>\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=text\",\"text_color\":\"globals\\/colors?id=3197874\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":false},{\"id\":\"7924f4d8\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"flex_justify_content\":\"center\",\"flex_align_items\":\"center\",\"padding\":{\"unit\":\"px\",\"top\":\"80\",\"right\":\"20\",\"bottom\":\"80\",\"left\":\"20\",\"isLinked\":false},\"flex_gap\":{\"column\":\"50\",\"row\":\"50\",\"isLinked\":true,\"unit\":\"px\",\"size\":50}},\"elements\":[{\"id\":\"7a45773\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"custom_css\":\"selector{\\n    background:linear-gradient(to right, var(--e-global-color-cae35c9) 0, var(--e-global-color-cae35c9) 33%,var(--e-global-color-4671584) 33%, var(--e-global-color-4671584) 66%, #fff 66%, #fff 100%);\\n}\",\"width\":{\"unit\":\"px\",\"size\":300,\"sizes\":[]},\"min_height\":{\"unit\":\"px\",\"size\":10,\"sizes\":[]},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[],\"isInner\":true},{\"id\":\"046f493\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"text\":\"Join Us!\",\"align\":\"center\",\"__globals__\":{\"background_color\":\"globals\\/colors?id=88133c5\",\"button_text_color\":\"globals\\/colors?id=3197874\",\"typography_typography\":\"globals\\/typography?id=98ba919\",\"border_color\":\"globals\\/colors?id=4478c39\"},\"text_padding\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"30\",\"bottom\":\"15\",\"left\":\"30\",\"isLinked\":false},\"border_border\":\"solid\",\"border_width\":{\"unit\":\"px\",\"top\":\"3\",\"right\":\"3\",\"bottom\":\"3\",\"left\":\"3\",\"isLinked\":true}},\"elements\":[],\"widgetType\":\"button\"},{\"id\":\"3683b6a6\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Discover all L.A.M.A. has to offer!<br>\\nTake some time to browse the website and reach out with any questions.\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=3197874\"},\"align\":\"center\",\"header_size\":\"h3\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false}]');
