INSERT INTO `wp_posts` VALUES (30,1,'2024-09-19 18:28:47','2024-09-19 18:28:47','<h5>Visit The Florida Motorcycle Safety Program (FMSP), Our Partners In Keeping Riders Safe On The Roads.</h5>		\n			<a href=\"http://fl-msp.com\">\n									Click Here To Visit FL-MSP.com\n					</a>\n			<h2>L.A.M.A.\'s Lookin\' Out For Each Other</h2>		\n		<p>The Latin American Motorcycle Association wants the roads to be safe for everyone. That\'s why all L.A.M.A. meetings contain a safety segment and our officers present free safety courses at least twice a year.</p>		\n													<img width=\"800\" height=\"524\" src=\"http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa-1024x671.jpg\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa-1024x671.jpg 1024w, http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa-300x196.jpg 300w, http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa-768x503.jpg 768w, http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa-600x393.jpg 600w, http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa.jpg 1376w\" sizes=\"(max-width: 800px) 100vw, 800px\" />													\n			<h5>L.A.M.A. Safety Course - Tampa, FL</h5>		\n			<h2>Take The Rider Survey!</h2>		\n		https://www.youtube.com/watch?v=bC0RqC04an4		\n			<a href=\"#\">\n									Sharable Video!\n					</a>','Motorcycle Safety & Awareness','','publish','closed','closed','','motorcycle-safety-awareness','','','2024-10-04 22:33:24','2024-10-04 22:33:24','',0,'http://lama.local/?page_id=30',0,'page','',0);
