INSERT INTO `wp_posts` VALUES (251,1,'2024-09-19 21:27:45','2024-09-19 21:27:45','http://lama.local/wp-content/uploads/2024/09/LAMA_Intro_Bkgnd.mp4		\n			<h2>Welcome to the Latin American Motorcycle Association (L.A.M.A.) \n</h2>		\n		<p>The Latin American Motorcycle Association (L.A.M.A.) is a Moto-Tourism club with Democratic ideals. It is one of the most active long-distance riding clubs in the world with 240 chapters in 26 countries and 5 continents. There are nearly 100 L.A.M.A. chapters in the United States alone, and the association is still growing.</p>		\n													<img width=\"772\" height=\"564\" src=\"http://lama.local/wp-content/uploads/2024/09/Travel_-_Garden_Group.png\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/09/Travel_-_Garden_Group.png 772w, http://lama.local/wp-content/uploads/2024/09/Travel_-_Garden_Group-300x219.png 300w, http://lama.local/wp-content/uploads/2024/09/Travel_-_Garden_Group-768x561.png 768w\" sizes=\"(max-width: 772px) 100vw, 772px\" />													\n			<h2>Our Mission</h2>		\n			<h4>To unite motorcycle enthusiasts in fellowship, promoting Peace, Love, Harmony and non-Violence worldwide, demonstrating through example that we can all live together in peace.</h4>		\n			<h2>Currently L.A.M.A. has chapters in 25 nations on 6 continents </h2>		\n													<img width=\"316\" height=\"274\" src=\"http://lama.local/wp-content/uploads/2024/09/54.png\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/09/54.png 316w, http://lama.local/wp-content/uploads/2024/09/54-300x260.png 300w\" sizes=\"(max-width: 316px) 100vw, 316px\" />													\n			Total Lane Miles In Florida			\n				0\n				K\n													<img width=\"451\" height=\"274\" src=\"http://lama.local/wp-content/uploads/2024/09/55.png\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/09/55.png 451w, http://lama.local/wp-content/uploads/2024/09/55-300x182.png 300w\" sizes=\"(max-width: 451px) 100vw, 451px\" />													\n			Motorcycles In Florid			\n				0\n				K\n			<a href=\"#\">\n									Learn More\n					</a>\n													<img width=\"800\" height=\"521\" src=\"http://lama.local/wp-content/uploads/2024/09/50-1024x667.jpg\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/09/50-1024x667.jpg 1024w, http://lama.local/wp-content/uploads/2024/09/50-300x195.jpg 300w, http://lama.local/wp-content/uploads/2024/09/50-768x500.jpg 768w, http://lama.local/wp-content/uploads/2024/09/50.jpg 1510w\" sizes=\"(max-width: 800px) 100vw, 800px\" />													\n													<img width=\"800\" height=\"521\" src=\"http://lama.local/wp-content/uploads/2024/09/51-1024x667.jpg\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/09/51-1024x667.jpg 1024w, http://lama.local/wp-content/uploads/2024/09/51-300x195.jpg 300w, http://lama.local/wp-content/uploads/2024/09/51-768x500.jpg 768w, http://lama.local/wp-content/uploads/2024/09/51.jpg 1510w\" sizes=\"(max-width: 800px) 100vw, 800px\" />													\n			<h2>Message from L.A.M.A. President and Founder Mario Nieves:</h2>		\n		<p style=\"margin: 0in; vertical-align: baseline;\">Thank you for visiting the home of the Latin American Motorcycle Association and the International Motorcycle Association. </p><p style=\"margin: 0in; vertical-align: baseline;\"> </p><p style=\"margin: 0in; vertical-align: baseline;\">Through these pages, you will learn more about being part of the Best Riders Association in the World! </p><p style=\"margin: 0in; vertical-align: baseline;\"> </p><p style=\"margin: 0in; vertical-align: baseline;\">We welcome working people from all walks of life to explore the world with us while enjoying the motorcycling lifestyle, spreading peace and love and making lifelong friendships.</p><p style=\"margin: 0in; vertical-align: baseline;\"> </p><p style=\"margin: 0in; vertical-align: baseline;\">Let’s Ride!</p><p style=\"margin: 0in; vertical-align: baseline;\"> </p><p style=\"margin: 0in; vertical-align: baseline;\">Best,</p><p style=\"margin: 0in; vertical-align: baseline;\">Mario Nieves</p>		\n			<h2>Get Connected With L.A.M.A. Today</h2>		\n			<a href=\"#\">\n									Click here\n					</a>','Home','','inherit','closed','closed','','2-revision-v1','','','2024-09-19 21:27:45','2024-09-19 21:27:45','',2,'http://lama.local/?p=251',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (252,1,'2024-09-19 21:27:45','2024-09-19 21:27:45','http://lama.local/wp-content/uploads/2024/09/LAMA_Intro_Bkgnd.mp4		\n			<h2>Welcome to the Latin American Motorcycle Association (L.A.M.A.) \n</h2>		\n		<p>The Latin American Motorcycle Association (L.A.M.A.) is a Moto-Tourism club with Democratic ideals. It is one of the most active long-distance riding clubs in the world with 240 chapters in 26 countries and 5 continents. There are nearly 100 L.A.M.A. chapters in the United States alone, and the association is still growing.</p>		\n													<img width=\"772\" height=\"564\" src=\"http://lama.local/wp-content/uploads/2024/09/Travel_-_Garden_Group.png\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/09/Travel_-_Garden_Group.png 772w, http://lama.local/wp-content/uploads/2024/09/Travel_-_Garden_Group-300x219.png 300w, http://lama.local/wp-content/uploads/2024/09/Travel_-_Garden_Group-768x561.png 768w\" sizes=\"(max-width: 772px) 100vw, 772px\" />													\n			<h2>Our Mission</h2>		\n			<h4>To unite motorcycle enthusiasts in fellowship, promoting Peace, Love, Harmony and non-Violence worldwide, demonstrating through example that we can all live together in peace.</h4>		\n			<h2>Currently L.A.M.A. has chapters in 25 nations on 6 continents </h2>		\n													<img width=\"316\" height=\"274\" src=\"http://lama.local/wp-content/uploads/2024/09/54.png\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/09/54.png 316w, http://lama.local/wp-content/uploads/2024/09/54-300x260.png 300w\" sizes=\"(max-width: 316px) 100vw, 316px\" />													\n			Total Lane Miles In Florida			\n				0\n				K\n													<img width=\"451\" height=\"274\" src=\"http://lama.local/wp-content/uploads/2024/09/55.png\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/09/55.png 451w, http://lama.local/wp-content/uploads/2024/09/55-300x182.png 300w\" sizes=\"(max-width: 451px) 100vw, 451px\" />													\n			Motorcycles In Florid			\n				0\n				K\n			<a href=\"#\">\n									Learn More\n					</a>\n													<img width=\"800\" height=\"521\" src=\"http://lama.local/wp-content/uploads/2024/09/50-1024x667.jpg\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/09/50-1024x667.jpg 1024w, http://lama.local/wp-content/uploads/2024/09/50-300x195.jpg 300w, http://lama.local/wp-content/uploads/2024/09/50-768x500.jpg 768w, http://lama.local/wp-content/uploads/2024/09/50.jpg 1510w\" sizes=\"(max-width: 800px) 100vw, 800px\" />													\n													<img width=\"800\" height=\"521\" src=\"http://lama.local/wp-content/uploads/2024/09/51-1024x667.jpg\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/09/51-1024x667.jpg 1024w, http://lama.local/wp-content/uploads/2024/09/51-300x195.jpg 300w, http://lama.local/wp-content/uploads/2024/09/51-768x500.jpg 768w, http://lama.local/wp-content/uploads/2024/09/51.jpg 1510w\" sizes=\"(max-width: 800px) 100vw, 800px\" />													\n			<h2>Message from L.A.M.A. President and Founder Mario Nieves:</h2>		\n		<p style=\"margin: 0in; vertical-align: baseline;\">Thank you for visiting the home of the Latin American Motorcycle Association and the International Motorcycle Association. </p><p style=\"margin: 0in; vertical-align: baseline;\"> </p><p style=\"margin: 0in; vertical-align: baseline;\">Through these pages, you will learn more about being part of the Best Riders Association in the World! </p><p style=\"margin: 0in; vertical-align: baseline;\"> </p><p style=\"margin: 0in; vertical-align: baseline;\">We welcome working people from all walks of life to explore the world with us while enjoying the motorcycling lifestyle, spreading peace and love and making lifelong friendships.</p><p style=\"margin: 0in; vertical-align: baseline;\"> </p><p style=\"margin: 0in; vertical-align: baseline;\">Let’s Ride!</p><p style=\"margin: 0in; vertical-align: baseline;\"> </p><p style=\"margin: 0in; vertical-align: baseline;\">Best,</p><p style=\"margin: 0in; vertical-align: baseline;\">Mario Nieves</p>		\n			<h2>Get Connected With L.A.M.A. Today</h2>		\n			<a href=\"#\">\n									Click here\n					</a>','Home','','inherit','closed','closed','','2-revision-v1','','','2024-09-19 21:27:45','2024-09-19 21:27:45','',2,'http://lama.local/?p=252',0,'revision','',0);
